class RegressionTests(unittest.TestCase):
    def test_attempts_is_total_calls(self):
        calls = []

        def operation():
            calls.append(1)
            raise RuntimeError("unavailable")

        with self.assertRaises(RuntimeError):
            solution.retry_call(operation, attempts=1)
        self.assertEqual(len(calls), 1)

        calls.clear()
        with self.assertRaises(RuntimeError):
            solution.retry_call(operation, attempts=3)
        self.assertEqual(len(calls), 3)

    def test_succeeds_after_retries(self):
        calls = []

        def operation():
            calls.append(1)
            if len(calls) < 2:
                raise ValueError("not yet")
            return "ok"

        self.assertEqual(solution.retry_call(operation, attempts=2), "ok")
        self.assertEqual(len(calls), 2)

    def test_preserves_original_exception_instance(self):
        error = RuntimeError("unavailable")

        def operation():
            raise error

        with self.assertRaises(RuntimeError) as ctx:
            solution.retry_call(operation, attempts=2)
        self.assertIs(ctx.exception, error)

    def test_non_matching_exception_propagates_immediately(self):
        calls = []

        def operation():
            calls.append(1)
            raise KeyError("boom")

        with self.assertRaises(KeyError):
            solution.retry_call(operation, attempts=3, retry_on=(ValueError,))
        self.assertEqual(len(calls), 1)

    def test_invalid_attempts_raise_value_error(self):
        for bad in (0, -1, 1.5, "3", None, True, False):
            with self.subTest(attempts=bad):
                calls = []

                def operation():
                    calls.append(1)
                    return "ok"

                with self.assertRaises(ValueError):
                    solution.retry_call(operation, attempts=bad)
                self.assertEqual(calls, [])

    def test_valid_attempts_accepted(self):
        self.assertEqual(solution.retry_call(lambda: 42, attempts=1), 42)


if __name__ == "__main__":
    unittest.main()
